	/* @Override */
	public TableComponentProvider<SymbolRowObject> showSymbols(CodeUnit codeUnit) {

		Objects.requireNonNull(codeUnit);

		Program program = codeUnit.getProgram();
		Address addr = codeUnit.getMinAddress();
		string title = "Labels at " + addr;

		TableComponentProvider<SymbolRowObject> provider = transientTableProviders.get(title);
		if (provider != null) {

			if (provider.isShowing()) {
				LabelFieldSymbolModel model = (LabelFieldSymbolModel) provider.getModel();
				reload(codeUnit, model);
				provider.toFront();
				return provider;
			}

			transientTableProviders.remove(title);
		}

		LabelFieldSymbolLoader loader =
			new LabelFieldSymbolLoader(codeUnit, int.MaxValue, true);
		Symbols symbols = loader.getSymbols();

		List<Symbol> list = symbols.getAllSymbols();

		HashSet<SymbolRowObject> rowObjects = list.stream()
				.map(s => new SymbolRowObject(s))
				.collect(Collectors.toCollection(HashSet.new));

		LabelFieldSymbolModel model =
			new LabelFieldSymbolModel(tool, program, rowObjects);
		provider = CreateSymbolTableAction.showTransientTable(tool, title, program, model);
		if (provider == null) {
			return null;
		}

		provider.setClosedCallback(() => {
			transientTableProviders.remove(title);
		});

		addActions(provider, model, codeUnit);

		transientTableProviders.put(title, provider);

		return provider;
	}

	private void addActions(TableComponentProvider<SymbolRowObject> provider,
			LabelFieldSymbolModel model, CodeUnit cu) {

		new ActionBuilder("Refresh", ToolConstants.SHARED_OWNER)
				.toolBarGroup("_", "1") // first
				.toolBarIcon(Icons.REFRESH_ICON)
				.helpLocation(new HelpLocation(HelpTopics.CODE_BROWSER, "Refresh_Labels"))
				.onAction(c => {
					reload(cu, model);
				})
				.buildAndInstallLocal(provider);

		new ActionBuilder("Delete", ToolConstants.SHARED_OWNER)
				.toolBarGroup("_", "2") // first
				.toolBarIcon(Icons.DELETE_ICON)
				.helpLocation(new HelpLocation(HelpTopics.CODE_BROWSER, "Delete_Label"))
				.enabledWhen(c => {
					GhidraTable table = provider.getTable();
					return table.getSelectedRowCount() > 0;
				})
				.onAction(c => {
					deleteSymbols(provider, model);
				})
				.buildAndInstallLocal(provider);
	}

	private void deleteSymbols(TableComponentProvider<SymbolRowObject> provider,
			LabelFieldSymbolModel model) {

		List<Symbol> symbols = new();

		GhidraTable table = provider.getTable();
		int[] rows = table.getSelectedRows();
		foreach (int row in rows) {
			SymbolRowObject ro = model.getRowObject(row);
			Symbol symbol = ro.getSymbol();
			if (symbol.isDeleted()) {
				// this symbol was deleted outside of the table and the table did not update
				model.removeObject(ro);
				continue;
			}

			symbols.add(symbol);
		}
		model.delete(symbols);
	}

	private void reload(CodeUnit cu, LabelFieldSymbolModel model) {
		LabelFieldSymbolLoader loader =
			new LabelFieldSymbolLoader(cu, int.MaxValue, true);
		Symbols symbols = loader.getSymbols();

		List<Symbol> list = symbols.getAllSymbols();

		HashSet<SymbolRowObject> rowObjects = list.stream()
				.map(s => new SymbolRowObject(s))
				.collect(Collectors.toCollection(HashSet.new));

		model.setData(rowObjects);
	}

	private class LabelFieldSymbolModel : TransientSymbolTableModel {

		public LabelFieldSymbolModel(ServiceProvider sp, Program program,
				HashSet<SymbolRowObject> rowObjects) : base(sp, program, rowObjects)
    {
		}

		public void setData(HashSet<SymbolRowObject> rowObjects) {
			this.rowObjects = rowObjects;
			reload();
		}

		/* @Override */
		protected void delete(List<Symbol> symbols) {
			base.delete(symbols);
		}

		/* @Override */
		protected TableColumnDescriptor<SymbolRowObject> createTableColumnDescriptor() {

			TableColumnDescriptor<SymbolRowObject> descriptor = base.createTableColumnDescriptor();

			//@formatter:off
			Set<string> visibleNames = new(Set.of(
				NameTableColumn.NAME, 
				SymbolTypeTableColumn.NAME,
				SourceTableColumn.NAME,
				ReferenceCountTableColumn.NAME));
			//@formatter:on

			List<DynamicTableColumn<SymbolRowObject,object,object>> allColumns = descriptor.getAllColumns();

			foreach (DynamicTableColumn<SymbolRowObject,object,object> column in allColumns) {
				string columnName = column.getColumnName();
				bool visible = visibleNames.contains(columnName);
				descriptor.setVisible(columnName, visible);
			}

			return descriptor;
		}
	}

//==================================================================================================
// Table Update Jobs
//==================================================================================================

	private abstract class AbstractSymbolUpdateJob : Job {

		protected Program program;

		AbstractSymbolUpdateJob(Program program) {
			this.program = program;
		}

		/* @Override */
		public void run(TaskMonitor taskMonitor) {
			if (program != currentProgram) {
				return;
			}
			doRun();
		}

		protected abstract void doRun();
	}

	private class CodeAddedRemoveJob : AbstractSymbolUpdateJob {

		private Address start;

		CodeAddedRemoveJob(Program program, Address start) : base(program)
    {
			this.start = start;
		}

		/* @Override */
		protected void doRun() {

			if (!symProvider.isShowingDynamicSymbols()) {
				return;
			}

			// Note: this code *should* be checking the entire address range to handle the case 
			//       where large address range was cleared.   This implementation will handle the
			//       case where individual code units are cleared.  This feature has been this way
			//       for many years.   The assumption is that most users are not showing dynamic
			//       symbols often, especially not when performing analysis or clearing large 
			//       address ranges.    Checking each address of the changed range is very slow.
			//       This code will need to be updated in the future if we decide updating the
			//       dynamic symbols in the symbol table is worth the cost.  For now, if the table
			//       becomes out-of-date, then user can simply close and re-open the table to 
			//       trigger an update.
			SymbolTable symbolTable = currentProgram.getSymbolTable();
			Symbol symbol = symbolTable.getPrimarySymbol(start);
			if (symbol != null && symbol.isDynamic()) {
				symProvider.symbolChanged(symbol);
				refProvider.symbolChanged(symbol);
			}
		}
	}

	private class SymbolAddedJob : AbstractSymbolUpdateJob {

		private Symbol symbol;

		SymbolAddedJob(Program program, Symbol symbol) : base(program)
    {
			this.symbol = symbol;
		}

		/* @Override */
		protected void doRun() {
			symProvider.symbolAdded(symbol);
			refProvider.symbolAdded(symbol);
		}
	}

	private class SymbolRemovedJob : AbstractSymbolUpdateJob {

		private long symbolId;
		private Address address;

		SymbolRemovedJob(Program program, Address address, long symbolId) : base(program)
    {
			this.address = address;
			this.symbolId = symbolId;
		}

		/* @Override */
		protected void doRun() {
			symProvider.symbolRemoved(symbolId);
			refProvider.symbolRemoved(symbolId);

			if (!symProvider.isShowingDynamicSymbols()) {
				return;
			}

			SymbolTable symbolTable = currentProgram.getSymbolTable();
			Symbol primaryAtRemove = symbolTable.getPrimarySymbol(address);
			if (primaryAtRemove != null && primaryAtRemove.isDynamic()) {
				// 
				symProvider.symbolChanged(primaryAtRemove);
				refProvider.symbolChanged(primaryAtRemove);
			}
		}
	}

	private class SymbolChangedJob : AbstractSymbolUpdateJob {

		private Symbol symbol;

		SymbolChangedJob(Program program, Symbol symbol) : base(program)
    {
			this.symbol = symbol;
		}

		/* @Override */
		protected void doRun() {
			symProvider.symbolChanged(symbol);
			refProvider.symbolChanged(symbol);
		}
	}

	private class SymbolSourceChangedJob : AbstractSymbolUpdateJob {

		private Symbol symbol;

		SymbolSourceChangedJob(Program program, Symbol symbol) : base(program)
    {
			this.symbol = symbol;
		}

		/* @Override */
		protected void doRun() {
			symProvider.symbolChanged(symbol);
		}
	}

	private class SymbolSetAsPrimaryJob : AbstractSymbolUpdateJob {

		private Symbol symbol;
		private Symbol oldPrimarySymbol;

		SymbolSetAsPrimaryJob(Program program, Symbol symbol, Symbol oldPrimarySymbol) : base(program)
    {
			this.symbol = symbol;
			this.oldPrimarySymbol = oldPrimarySymbol;
		}

		/* @Override */
		protected void doRun() {

			symProvider.symbolChanged(symbol);
			if (oldPrimarySymbol != null) {
				symProvider.symbolChanged(oldPrimarySymbol);
			}
		}
	}

	private class ReferenceAddedJob : AbstractSymbolUpdateJob {

		private Reference reference;

		ReferenceAddedJob(Program program, Reference reference) : base(program)
    {
			this.reference = reference;
		}

		/* @Override */
		protected void doRun() {

			Address toAddr = reference.getToAddress();
			bool isValid = toAddr.isMemoryAddress() || toAddr.isExternalAddress();
			if (!isValid) {
				return;
			}

			SymbolTable symbolTable = program.getSymbolTable();
			Symbol symbol = symbolTable.getSymbol(reference);
			if (symbol == null) {
				return;
			}

			if (!symbol.isDynamic() || symProvider.isShowingDynamicSymbols()) {
				symProvider.symbolChanged(symbol);
				refProvider.symbolChanged(symbol);
			}
		}
	}

	private class ReferenceRemovedJob : AbstractSymbolUpdateJob {

		private Reference reference;

		ReferenceRemovedJob(Program program, Reference reference) : base(program)
    {
			this.reference = reference;
		}

		/* @Override */
		protected void doRun() {

			Address toAddr = reference.getToAddress();
			bool isValid = toAddr.isMemoryAddress() || toAddr.isExternalAddress();
			if (!isValid) {
				return;
			}

			SymbolTable symbolTable = program.getSymbolTable();
			Symbol symbol = symbolTable.getSymbol(reference);
			if (symbol != null) {
				if (!symbol.isDynamic() || symProvider.isShowingDynamicSymbols()) {
					symProvider.symbolChanged(symbol);
					refProvider.symbolChanged(symbol);
				}
			}
			else if (toAddr.isMemoryAddress() && symProvider.isShowingDynamicSymbols()) {
				long dynamicSymbolId = symbolTable.getDynamicSymbolID(toAddr);
				symProvider.symbolRemoved(dynamicSymbolId);
				refProvider.symbolRemoved(dynamicSymbolId);
			}
		}
	}

	private class ExternalEntryChangedJob : AbstractSymbolUpdateJob {

		private Address address;

		ExternalEntryChangedJob(Program program, Address address) : base(program)
    {
			this.address = address;
		}

		/* @Override */
		protected void doRun() {

			SymbolTable symbolTable = program.getSymbolTable();
			Symbol[] symbols = symbolTable.getSymbols(address);
			foreach (Symbol element in symbols) {
				symProvider.symbolChanged(element);
				refProvider.symbolChanged(element);
			}
		}
	}

}
